#!/usr/bin/env python3
"""Self-extracting restore for hindawi sutram v11 (spine).
Usage: python3 restore_sutram_v11.py [target_dir]
"""
import os, sys, base64
FILES = {
    'sutram_tool/__init__.py': 'IyBzdXRyYW1fdG9vbCBwYWNrYWdlCg==',
    'sutram_tool/ast_nodes.py': '',
    'sutram_tool/chhandas.py': '',
    'sutram_tool/cli.py': '',
    'sutram_tool/codec.py': '',
    'sutram_tool/forward.py': '',
    'sutram_tool/katapayadi.py': '',
    'sutram_tool/lexer.py': '',
    'sutram_tool/library_spine.py': '',
    'sutram_tool/mappings.py': '',
    'sutram_tool/numerals.py': '',
    'sutram_tool/parser.py': '',
    'sutram_tool/reverse.py': '',
    'sutram_tool/sandhi_panini.py': '',
    'sutram_tool/sandhi_samasa.py': '',
    'sutram_tool/true_chhandas.py': '',
    'REGRESSION.md': '',
}
def main():
    target = sys.argv[1] if len(sys.argv)>1 else "sutram_tool_restore"
    for rel,b64 in FILES.items():
        fp=os.path.join(target, rel)
        d=os.path.dirname(fp)
        if d: os.makedirs(d, exist_ok=True)
        with open(fp,"w",encoding="utf-8") as f:
            f.write(base64.b64decode(b64).decode("utf-8"))
    print(f"Restored {len(FILES)} files to {target}/")
if __name__=="__main__": main()